use blent_config::{camera::CameraProfile, tablets::Identity, workspace::{Catalog, Device, Presence}};
#[path = "/backups/disk2/projects/blent/gui/src/media_owner.rs"] mod media_owner;
#[derive(Default)]
struct Status { tablets: Vec<Device>, display: Option<blent_config::display_control::Snapshot>, inventory_error: Option<String> }
struct Connection;
impl Connection { fn tablets(&self) -> Vec<Device> { vec![] } }
struct App { camera: media_owner::Owner, microphone: media_owner::Owner, speakers: media_owner::Owner, selected: Option<Identity>, connection: Connection }
impl App {
    fn collect_workspace_devices(&mut self, status: &Status) -> Result<Catalog, String> {
        let mut catalog = Catalog::new(1024).unwrap();
        for device in status
            .tablets
            .iter()
            .cloned()
            .chain(self.connection.tablets())
        {
            catalog.insert(device).map_err(|error| error.to_string())?;
        }
        if let Some(display) = &status.display {
            add_display_devices(&mut catalog, display)?;
        }
        for target in [
            self.camera.target(),
            self.microphone.target(),
            self.speakers.target(),
            self.selected.as_ref(),
        ]
        .into_iter()
        .flatten()
        {
            if !catalog
                .devices()
                .iter()
                .any(|device| device.identity() == target)
            {
                let device =
                    Device::new(target.clone(), target.label(), Presence::Unknown, false).unwrap();
                catalog.insert(device).map_err(|error| error.to_string())?;
            }
        }
        Ok(catalog)
    }


}
fn add_display_devices(
    catalog: &mut Catalog,
    snapshot: &blent_config::display_control::Snapshot,
) -> Result<(), String> {
    snapshot.validate().map_err(|error| error.to_string())?;
    for assignment in &snapshot.assignments {
        let identity = assignment
            .target
            .identity()
            .map_err(|error| error.to_string())?;
        let device = Device::new(
            identity.clone(),
            identity.label(),
            Presence::Unknown,
            assignment.phase == blent_config::display_control::Phase::Assigned,
        )
        .map_err(|error| error.to_string())?;
        catalog.insert(device).map_err(|error| error.to_string())?;
    }
    Ok(())
}


fn merge_inventory(status: &mut Status, inventory: &[blent_config::workspace::Device]) {
    let mut catalog = blent_config::workspace::Catalog::new(1024).unwrap();
    for device in status.tablets.drain(..).chain(inventory.iter().cloned()) {
        if let Err(error) = catalog.insert(device) {
            status.inventory_error = Some(error.to_string());
            break;
        }
    }
    status.tablets = catalog.into_devices();
}


fn serial(serial: &str) {
    let profile = CameraProfile { serial: Some(serial.into()), ..Default::default() };
    let mut camera = media_owner::Owner::default();
    camera.admit(media_owner::identity(profile.target().unwrap()));
    let mut app = App { camera, microphone: Default::default(), speakers: Default::default(), selected: None, connection: Connection };
    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| app.collect_workspace_devices(&Status::default())));
    println!("T1295 serial_bytes={} profile_valid={} catalog_panicked={}", serial.len(), profile.validate().is_ok(), result.is_err());
}
fn inventory() {
    let assigned = Device::new(Identity::Adb("assigned-only".into()), "Assigned".into(), Presence::Connected, true).unwrap();
    let discovered = (0..1024).map(|index| Device::new(Identity::Adb(format!("tablet-{index}")), "Tablet".into(), Presence::Unknown, false).unwrap()).collect::<Vec<_>>();
    let mut status = Status { tablets: vec![assigned], ..Default::default() };
    merge_inventory(&mut status, &discovered);
    let merge_error = status.inventory_error.clone();
    // Exact next assignment in Platform::dynamic after successful discovery.
    status.inventory_error = None;
    println!("T1299 union=1025 retained={} merge_error={merge_error:?} published_error={:?}", status.tablets.len(), status.inventory_error);
}
fn main() {
    serial(&"a".repeat(1024));
    serial(&"a".repeat(1025));
    serial("bad\nserial");
    serial("");
    inventory();
}

