use blent_config::{camera::CameraProfile, workspace::{Device, Presence}};
#[path = "/backups/disk2/projects/blent/gui/src/media_owner.rs"]
mod media_owner;

fn main() {
    for serial in ["".to_owned(), "bad\nserial".to_owned(), "a".repeat(1024), "a".repeat(1025)] {
        let options = CameraProfile { serial: Some(serial.clone()), ..CameraProfile::default() };
        let target = media_owner::identity(options.target().unwrap()).unwrap();
        let mut owner = media_owner::Owner::default();
        owner.prepare(&Some(target.clone())).unwrap();
        owner.admit(Some(target));
        let admitted = owner.target().unwrap().clone();
        let result = Device::new(admitted.clone(), admitted.label(), Presence::Unknown, false);
        println!("serial_bytes={} control={} profile_valid={} admitted=true workspace_valid={}", serial.len(), serial.chars().any(char::is_control), options.validate().is_ok(), result.is_ok());
    }
}
